using OcctSharp.DocumentProjections;
using OcctSharp.DocumentAssociations;
using OcctSharp.StepCafWorkspaces;
using OcctSharp.XdeMetadataWorkspaces;
namespace OcctSharp.Tests.Shared;
internal static class BatchBCAssociationWorkflow {
 internal static void Verify(DocumentAssociationContext associations,DocumentProjectionLabel shape,DocumentProjectionLabel reference,DocumentProjectionLabel naming,DocumentProjectionLabel dimension,DocumentProjectionLabel clip,DocumentProjectionLabel view){
  var a=associations.Snapshot(reference);if(a.ReferenceEntry!=shape.Entry||a.AttributeCount==0)throw new InvalidOperationException("BC exact generic reference failed.");
  var n=associations.Snapshot(naming).Naming;if(n is not{IsDefined:true,NativeType:1,Index:0}||n.ContextEntry!=shape.Entry||n.StopEntry!=shape.Entry||n.ArgumentEntries.Count!=1||n.ArgumentEntries[0]!=shape.Entry||n.StoredShapeType is null)throw new InvalidOperationException("BC initialized direct naming diagnostics failed.");
  var d=associations.Snapshot(dimension).Dimension;if(d is null||!d.IsLocked||d.FirstEntries.Single()!=shape.Entry)throw new InvalidOperationException("BC structural dimension association failed.");
  if(!associations.Snapshot(shape).ReferencingDimensions.Contains(dimension.Entry))throw new InvalidOperationException("BC inverse dimension association failed.");
  var c=associations.Snapshot(clip).Clipping;if(c is null||c.Name!="剖切🙂"||c.IsCapping!=true||!c.ViewEntries.Contains(view.Entry)||Math.Abs(c.Plane.C-1)>1e-12||Math.Abs(c.Plane.D+1)>1e-12)throw new InvalidOperationException("BC exact clipping plane/view association failed.");
  if(!associations.Snapshot(view).ClippingPlaneEntries.Contains(clip.Entry))throw new InvalidOperationException("BC inverse clip/view association failed.");
 }
 internal static void RunNative(){string root=Path.Combine(Path.GetTempPath(),"OcctSharp.BC."+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{using var box=ShapeFactory.CreateBox(2,3,4);string step=Path.Combine(root,"seed.step");ShapeExchange.WriteStep(box,step);using var imported=StepCafFiles.Read(step);var doc=imported.Document;doc.SetUndoLimit(10);using var context=DocumentProjectionContext.Bind(doc);using var associations=DocumentAssociationContext.Bind(context);using var metadata=XdeMetadataContext.Bind(context);var shape=context.GetLabel(imported.Diagnostics.FreeRoots.Single().Entry);var main=context.GetLabel("0:1");doc.NewCommand();var reference=associations.NewChild(main);associations.ReplaceReferences([new(reference,shape)]);var naming=associations.CreateDirectNamingReference(main,shape);var dimension=associations.CreateDimensionAssociation("explicit link",shape);associations.SetDimensionLocked(dimension,true);var view=metadata.CreateView("association view",[shape]);var clip=associations.CreateClippingPlane("剖切🙂",new(0,0,1,-1),true);associations.SetViewClippingPlanes(view,[clip]);if(!doc.CommitCommand())throw new InvalidOperationException("BC initial command failed.");Verify(associations,shape,reference,naming,dimension,clip,view);doc.NewCommand();associations.ReplaceReferences([new(reference,null)]);associations.SetDimensionLocked(dimension,false);associations.UpdateClippingPlane(clip,"changed",new(0,0,1,-2),false);if(!doc.CommitCommand()||!doc.Undo())throw new InvalidOperationException("BC edit/undo failed.");Verify(associations,shape,reference,naming,dimension,clip,view);if(!doc.Redo()||associations.Snapshot(reference).ReferenceEntry is not null||associations.Snapshot(dimension).Dimension!.IsLocked)throw new InvalidOperationException("BC redo failed.");if(!doc.Undo())throw new InvalidOperationException("BC restore failed.");var copied=associations.Snapshot(clip);imported.Dispose();if(copied.Clipping?.Name!="剖切🙂")throw new InvalidOperationException("BC detached lifetime failed.");}finally{Directory.Delete(root,true);}}
#if !DIRECT_MODULE_CONSUMER
 internal static void RunFacade(){string root=Path.Combine(Path.GetTempPath(),"OcctSharp.BC.Persistent."+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{using var doc=XdeDocument.Create();using var shape=ShapeFactory.CreateBox(2,3,4);string first,second,definition,assembly,reference,naming,dimension,clip,view;using(var transaction=doc.BeginTransaction("BC repeated instance associations")){var part=doc.AddShape(shape,"part");var a=doc.AddAssembly("assembly");using var location=TopLocLocation.Identity;var one=doc.AddComponent(a,part,location);var two=doc.AddComponent(a,part,location);first=one.Entry;second=two.Entry;definition=part.Entry;assembly=a.Entry;using var associations=DocumentAssociationContext.Bind(doc.Projections);using var metadata=XdeMetadataContext.Bind(doc.Projections);DocumentProjectionLabel oneLabel=doc.Projections.GetLabel(first),twoLabel=doc.Projections.GetLabel(second);var main=doc.Projections.GetLabel("0:1");var refLabel=associations.NewChild(main);reference=refLabel.Entry;associations.ReplaceReferences([new(refLabel,oneLabel)]);naming=associations.CreateDirectNamingReference(main,doc.Projections.GetLabel(definition)).Entry;var dim=associations.CreateDimensionAssociation("two occurrences",oneLabel,twoLabel);dimension=dim.Entry;associations.SetDimensionLocked(dim,true);var v=metadata.CreateView("repeat view",[oneLabel]);view=v.Entry;var plane=associations.CreateClippingPlane("剖切🙂",new(0,0,1,-1),true);clip=plane.Entry;associations.SetViewClippingPlanes(v,[plane]);if(!transaction.Commit())throw new InvalidOperationException("BC facade command failed.");}
  using(var context=DocumentAssociationContext.Bind(doc.Projections)){var a=context.Snapshot(doc.Projections.GetLabel(assembly)).Assembly;if(a is null||!a.IsAssembly||a.ComponentEntries.Count!=2)throw new InvalidOperationException("BC assembly copied diagnostics failed.");foreach(string entry in new[]{first,second})if(context.Snapshot(doc.Projections.GetLabel(entry)).Assembly?.ReferredEntry!=definition)throw new InvalidOperationException("BC repeated-instance source identity failed.");var d=context.Snapshot(doc.Projections.GetLabel(dimension)).Dimension;if(d is null||d.FirstEntries.Single()!=first||d.SecondEntries.Single()!=second||context.Snapshot(doc.Projections.GetLabel(definition)).ReferencingDimensions.Count!=0)throw new InvalidOperationException("BC dimension association leaked across occurrences.");}
  foreach(var format in new[]{DocumentStorageFormat.BinXcaf,DocumentStorageFormat.XmlXcaf}){string file=Path.Combine(root,format==DocumentStorageFormat.BinXcaf?"model.xbf":"model.xml");doc.Save(file,format);using var reopened=XdeDocument.Open(file);using var context=DocumentAssociationContext.Bind(reopened.Projections);if(context.Snapshot(reopened.Projections.GetLabel(reference)).ReferenceEntry!=first||context.Snapshot(reopened.Projections.GetLabel(naming)).Naming?.ContextEntry!=definition||context.Snapshot(reopened.Projections.GetLabel(dimension)).Dimension?.SecondEntries.Single()!=second||context.Snapshot(reopened.Projections.GetLabel(clip)).Clipping?.ViewEntries.Single()!=view)throw new InvalidOperationException("BC Bin/XML exact association persistence failed.");}}
 finally{Directory.Delete(root,true);}}
#endif
 internal static void Run(){RunNative();
#if !DIRECT_MODULE_CONSUMER
 RunFacade();
#endif
 }
}
